
const KEY='wlog-v1';
let S={workouts:[],logs:[]};
try{const r=localStorage.getItem(KEY);if(r)S=JSON.parse(r)}catch(e){}
S.body=S.body||[];S.profile=S.profile||{};S.settings=Object.assign({language:(S.settings||{}).language||'ru',theme:'system',units:'kg',rest:90,notifications:false},S.settings||{});
let supabase=null,authUser=null,syncTimer=null,syncMessage='Не выполнен вход — данные пока хранятся в этом браузере.';
const save=()=>{
 try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}
 if(authUser&&supabase){
  clearTimeout(syncTimer);
  syncMessage='Сохранение…';
  syncTimer=setTimeout(syncCloudData,500);
 }
};
async function syncCloudData(){
 if(!authUser||!supabase)return;
 const {error}=await supabase.from('user_data').upsert({
  user_id:authUser.id,profile:S.profile||{},settings:S.settings||{},
  workouts:S.workouts||[],logs:S.logs||[],body:S.body||[],updated_at:new Date().toISOString()
 });
 syncMessage=error?'Ошибка синхронизации: '+error.message:'Синхронизировано с облаком';
 const el=document.getElementById('cloud-status');if(el)el.textContent=syncMessage;
}
async function loadCloudData(user){
 const {data,error}=await supabase.from('user_data').select('*').eq('user_id',user.id).maybeSingle();
 if(error)throw error;
 if(data){
  S={workouts:Array.isArray(data.workouts)?data.workouts:[],logs:Array.isArray(data.logs)?data.logs:[],
   body:Array.isArray(data.body)?data.body:[],profile:data.profile&&typeof data.profile==='object'?data.profile:{},
   settings:Object.assign({language:'ru',theme:'system',units:'kg',rest:90,notifications:false},data.settings||{})};
  try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}
  syncMessage='Данные загружены из облака';
 }else{
  await syncCloudData();
 }
}
async function setAuthenticatedUser(user){
 authUser=user;
 if(user){await loadCloudData(user)}
 render();
}
async function initSupabase(){
 try{
  const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');
  supabase=createClient('https://wxpvlphfblxvijwrwtjm.supabase.co','sb_publishable_7KUM95G01M7mrWng3EoSUA_hbW6vRSg');
  const {data,error}=await supabase.auth.getSession();
  if(error)throw error;
  if(data.session?.user)await setAuthenticatedUser(data.session.user);
  supabase.auth.onAuthStateChange(async(event,session)=>{
   if(event==='SIGNED_OUT'){authUser=null;syncMessage='Вы вышли из аккаунта';render()}
  });
 }catch(error){
  syncMessage='Не удалось подключиться к Supabase: '+error.message;
  render();
 }
}
async function authAction(mode,email,password){
 const status=document.getElementById('auth-status');
 if(status)status.textContent='Выполняется…';
 const result=mode==='signup'
  ?await supabase.auth.signUp({email,password})
  :await supabase.auth.signInWithPassword({email,password});
 if(result.error){
  if(status){
   const lang=S.settings?.language||'ru';
   const invalidCredentials={
    ru:'Неверный адрес электронной почты или пароль.',
    en:'Incorrect email address or password.',
    de:'Falsche E-Mail-Adresse oder falsches Passwort.',
    es:'Correo electrónico o contraseña incorrectos.',
    fr:'Adresse e-mail ou mot de passe incorrect.',
    zh:'电子邮箱或密码不正确。',
    ja:'メールアドレスまたはパスワードが正しくありません。',
    hi:'ईमेल पता या पासवर्ड गलत है।'
   };
   status.textContent=result.error.message==='Invalid login credentials'
    ?(invalidCredentials[lang]||invalidCredentials.ru)
    :result.error.message;
  }
  return;
 }
 if(result.data.session?.user){
  try{await setAuthenticatedUser(result.data.session.user)}
  catch(error){if(status)status.textContent='Ошибка загрузки данных: '+error.message}
 }else if(status){
  status.textContent='Проверь почту и подтверди регистрацию, затем войди в аккаунт.';
 }
}

