function showDeleteAccountDialog(){
 const overlay=h('div',{class:'confirm-overlay',role:'presentation'});
 const dialog=h('section',{class:'confirm-dialog',role:'alertdialog','aria-modal':'true','aria-labelledby':'delete-account-title','aria-describedby':'delete-account-description'});
 const title=h('h2',{id:'delete-account-title'},tr('Удалить аккаунт'));
 const desc=h('p',{id:'delete-account-description'},tr('Вы действительно хотите навсегда удалить аккаунт и все тренировочные данные в облаке? Это действие нельзя отменить.'));
 const status=h('p',{class:'mut',role:'status','aria-live':'polite'});
 const cancel=h('button',{class:'b',type:'button',onclick:()=>overlay.remove()},tr('Отмена'));
 const confirm=h('button',{class:'b danger-button',type:'button',onclick:async()=>{
  if(confirm.disabled)return;
  confirm.disabled=true;cancel.disabled=true;status.textContent=tr('Удаление аккаунта…');
  try{
   const {data:{session}}=await supabase.auth.getSession();
   if(!session?.access_token)throw new Error('No active session');
   const response=await fetch('https://training-journal-api.ts9187814243.workers.dev/api/account/delete',{
    method:'POST',headers:{'Authorization':'Bearer '+session.access_token,'Content-Type':'application/json'}
   });
   const result=await response.json().catch(()=>({}));
   if(!response.ok){const diagnostic=[result.error,result.stage?'stage='+result.stage:'',result.upstreamStatus?'HTTP '+result.upstreamStatus:'',result.detail||''].filter(Boolean).join(' | ');throw new Error(diagnostic||'Delete failed');}
   clearTimeout(syncTimer);authUser=null;S={workouts:[],logs:[],body:[],profile:{},settings:{language:'ru',theme:'system',units:'kg',rest:90,notifications:false}};
   localStorage.removeItem(KEY);await supabase.auth.signOut({scope:'local'}).catch(()=>{});
   settingsOpen=false;overlay.remove();render();
  }catch(error){
   console.error('Account deletion failed:',error);
   status.textContent=tr('Не удалось удалить аккаунт. Попробуйте ещё раз.')+(error.message&&error.message!=='Delete failed'?' ('+error.message+')':'');
   confirm.disabled=false;cancel.disabled=false;
  }
 }},tr('Удалить навсегда'));
 dialog.append(title,desc,h('div',{class:'confirm-actions'},cancel,confirm),status);
 overlay.append(dialog);
 overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove()});
 const onKey=e=>{if(e.key==='Escape'){overlay.remove();document.removeEventListener('keydown',onKey)}};
 document.addEventListener('keydown',onKey);
 document.body.append(overlay);confirm.focus();
}
